import {feverRank} from './fever.mjs';
const fmt=n=>Math.floor(n).toLocaleString('ja-JP');
export function feverCard(record,saved){return `<p class="fever-intro">90秒、掘りまくろう。<br><b>下へ自動掘削 · 敵は一撃 · ミスしても最後まで</b></p><div class="fever-best-card"><span>PERSONAL BEST</span><strong>${fmt(record.score)}</strong><small>最高コンボ ${fmt(record.combo)} / ${record.runs} PLAY</small></div>${saved?'<button class="primary fever-primary" data-action="fever-continue">90秒のつづきへ <span>↗</span></button><button class="secondary" data-action="fever-new-confirm">新しい90秒をはじめる</button>':'<button class="primary fever-primary" data-action="fever-new">採掘フィーバーを遊ぶ <span>↗</span></button>'}<button class="text-button" data-action="guide">遊び方を見る</button>`;}
export function feverPause(g){return `<p class="eyebrow">FEVER MINING / PAUSED</p><h2>ひとやすみ。</h2><p class="modal-sub">残り ${g.fever.remaining.toFixed(1)} 秒 · ${fmt(g.fever.score)} POINTS<br>時間は止まっています。通常探索とは別に自動保存。</p><div class="button-stack"><button class="primary fever-primary" data-action="resume">採掘にもどる</button><button class="secondary" data-action="guide">フィーバーの遊び方</button><button class="text-button" data-action="home">保存してタイトルへ</button></div>`;}
export function feverGuide(){return `<p class="eyebrow">FEVER MINING / QUICK GUIDE</p><h2>左右だけで、大連鎖。</h2><div class="guide-content"><div class="guide-item"><span class="guide-icon">↔</span><div><b>下へは自動。左右で鉱脈を狙う</b><p>左右かGOで90秒がスタート。左右をタップ・長押しして進路を選ぼう。大ボタンの長押しで加速、小ボタンで3.5秒ごとに無料の爆破。PCは←→ / A・D、Spaceで加速、Xで爆破。</p></div></div><div class="guide-item"><span class="guide-icon">✦</span><div><b>群れも岩も、一気に砕く</b><p>同色の鉱脈はまとめて粉砕。落下先でつながると追加連鎖。敵は一撃で倒せ、爆発や横方向の衝撃波で周囲を巻き込む。宝石は自動回収。ミスは倍率とゲージが少し下がるだけで、死なずに最後まで遊べる。</p></div></div><div class="guide-item"><span class="guide-icon">ϟ</span><div><b>10秒間の3列フィーバー</b><p>連鎖と撃破でゲージをためると自動発動。10秒間は3列掘削＋スコア3倍。通常時も連鎖で最大8倍になり、フィーバー中は最大24倍！</p></div></div><div class="guide-item"><span class="guide-icon">↑</span><div><b>掘る流れのまま、強くなる</b><p>20秒で通常掘削が2列に、45秒で敵の誘爆が強化。最後の12秒には巨大な黄金鉱脈が登場する。途中の選択画面はなく、90秒で結果発表。ポーズ・ガイド・アプリ切り替えでは時間が止まる。</p></div></div></div><button class="primary" data-action="guide-back">もどる</button>`;}
export function feverResult(g,record,newBest){const f=g.fever;return `<div class="fever-summary"><p class="eyebrow">90 SECONDS / ${newBest?'NEW PERSONAL BEST!':'MINING COMPLETE'}</p><h2>掘りきった！</h2><div class="fever-result-score"><span>RANK <b>${feverRank(f.score)}</b></span><strong>${fmt(f.score)}</strong><small>POINTS · BEST ${fmt(record.score)}</small></div></div><div class="fever-details"><div class="stat-grid"><div class="stat-cell"><small>最大コンボ</small><strong>${f.maxCombo}</strong></div><div class="stat-cell"><small>フィーバー</small><strong>${f.activations}</strong><span>回</span></div><div class="stat-cell"><small>砕いたブロック</small><strong>${fmt(g.stats.blocks)}</strong></div><div class="stat-cell"><small>倒した敵</small><strong>${g.stats.kills}</strong></div></div><div class="button-stack"><button class="primary fever-primary" data-action="fever-retry">同じ鉱脈でもう一度 <span>↻</span></button><button class="secondary" data-action="fever-new">別の鉱脈で90秒</button><button class="text-button" data-action="home">タイトルへ</button></div></div>`;}

export function feverHud($,g,record,home){
  const active=!home&&g.arcade==='fever';$('fever-hud').hidden=!active;$('game-shell').classList.toggle('fever-mode',active);$('layout').classList.toggle('arcade-layout',active);$('game-shell').classList.toggle('is-fever',active&&g.fever.active>0);
  $('control-hint').innerHTML=active?'左右で進路<br><span>下へは自動</span>':'移動・掘削<br><span>長押しで連続</span>';
  if(!home)$('theme-color').setAttribute('content',active?'#fff4db':'#0c1522');
  if(!active)return;const f=g.fever;
  $('fever-score').textContent=fmt(f.score);$('fever-best').textContent=fmt(Math.max(record.score,f.score));$('fever-time').textContent=Math.max(0,f.remaining).toFixed(1);$('fever-time').classList.toggle('urgent',f.remaining<=12);
  $('fever-combo').textContent=`${g.combo} COMBO · ×${g.multiplier}`;$('fever-fill').style.width=(f.active>0?f.active/10*100:f.meter)+'%';$('fever-gauge-label').textContent=f.active>0?`FEVER! 3列掘削 · 残り ${f.active.toFixed(1)}s`:`FEVER ${Math.floor(f.meter)}% · 連鎖と撃破でためよう`;
  $('fever-hint').textContent=!g.started?'左右かGOでスタート':f.finale?'LAST SPURT · 黄金の巨大鉱脈を狙おう':f.upgrades>=2?'2列掘削 ＋ 誘爆強化 · 長押しで加速':f.upgrades>=1?'2列掘削にパワーアップ！': '左右で鉱脈を選ぶ · 敵を倒して誘爆';
  $('cast-name').textContent=g.started?'加速':'GO';$('cast-cost').textContent=g.started?'長押しブースト':'タップで開始';$('rush').setAttribute('aria-label',g.started?'長押しで自動掘削を加速':'採掘フィーバーを開始');$('rush').style.setProperty('--element-color',f.active>0?'#ffd16f':'#ffad75');
  $('pulse-text').textContent=g.player.pulseTimer>0?g.player.pulseTimer.toFixed(1)+'s':'ドカン';$('pulse').setAttribute('aria-label','無料の爆破 3.5秒ごとに使用可能');$('pulse-cooldown').style.height=Math.min(100,g.player.pulseTimer/3.5*100)+'%';
}
